REPAIR_LAB = (("ERL IIC", "IIC"),)


def restrict_repair_lab(apps, schema_editor):
    """Close the IIC Electronic Repair lab to all but OIC requests before it can be made available."""
    Equipment = apps.get_model("equipment", "Equipment")
    Log = apps.get_model("equipment", "EquipmentConfigAuditLog")
    for code, dept_code in REPAIR_LAB:
        for eq in Equipment.objects.filter(code=code, internal_department__code=dept_code):
            if eq.oic_requests_only:
                continue
            Equipment.objects.filter(pk=eq.pk).update(oic_requests_only=True, oic_request_registration_enabled=True)
            Log.objects.create(
                equipment_id=eq.pk,
                equipment_code=eq.code or "",
                equipment_name=eq.name or "",
                object_type="Equipment",
                object_id=str(eq.pk),
                object_label=eq.name or "",
                action="UPDATED",
                setting="oic_requests_only",
                setting_label="Only Officers In-charge Can Raise Requests",
                previous_value="No",
                new_value="Yes",
                is_system=True,
                source="SYSTEM",
                process="Migration 0262_oic_requests_only_and_audit",
            )


